class WindscriptError(Exception):
    def __init__(self, line: int, msg: str):
        super().__init__(f"Windscript error at line {line}: {msg}")
        self.line = line
        self.msg = msg


def _tokenize(s: str) -> list[str]:
    out, i, n = [], 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in "#":
            break
        if c in "\"'":
            q, i = c, i + 1
            buf = []
            while i < n and s[i] != q:
                if s[i] == "\\" and i + 1 < n:
                    buf.append(s[i + 1]); i += 2
                else:
                    buf.append(s[i]); i += 1
            i += 1
            out.append('"' + "".join(buf) + '"')
            continue
        if c == "," :
            out.append(",")
            i += 1
            continue
        if s.startswith("<=", i) or s.startswith(">=", i) or s.startswith("==", i) or s.startswith("!=", i):
            out.append(s[i:i+2]); i += 2
            continue
        if c in "<>":
            out.append(c); i += 1
            continue
        j = i
        while j < n and not s[j].isspace() and s[j] not in ',#"\'<>!=':
            j += 1
        if j == i:
            out.append(c); i += 1
        else:
            out.append(s[i:j]); i = j
    return out


def _unq(t: str) -> str:
    if t and t[0] in "\"'" and t[-1] == t[0]:
        return t[1:-1]
    return t


def _is_num(t: str) -> bool:
    try:
        float(t)
        return True
    except ValueError:
        return False


def _vec(tokens, i):
    nums = []
    while i < len(tokens) and (tokens[i] == "," or _is_num(tokens[i])):
        if tokens[i] != ",":
            nums.append(float(tokens[i]))
        i += 1
    return nums, i


def _parse_cond_atom(tokens):
    if not tokens:
        return {"type": "flag", "left": "true"}
    if tokens[0] == "key":
        key = tokens[1] if len(tokens) > 1 else "W"
        state = "held"
        if len(tokens) > 2 and tokens[2] in ("pressed", "held", "released"):
            state = tokens[2]
        return {"type": "key", "key": key, "state": state}
    for k, op in enumerate(tokens):
        if op in ("<=", ">=", "==", "!=", "<", ">", "is"):
            return {"type": "cmp", "left": tokens[k-1] if k else "0",
                    "op": "==" if op == "is" else op,
                    "right": " ".join(tokens[k+1:]) if k+1 < len(tokens) else "0"}
    return {"type": "flag", "left": tokens[0]}


def _parse_cond(tokens):
    parts, ops, cur = [], [], []
    for t in tokens:
        if t in ("and", "or"):
            parts.append(_parse_cond_atom(cur))
            ops.append(t)
            cur = []
        else:
            cur.append(t)
    if not parts:
        return _parse_cond_atom(tokens)
    parts.append(_parse_cond_atom(cur))
    return {"type": "bool", "parts": parts, "ops": ops}


def _parse_when(tokens, lineno):
    if not tokens:
        raise WindscriptError(lineno, "empty when")
    body_head = tokens[:]
    if body_head[0] == "scene" and len(body_head) > 1 and body_head[1] in ("starts", "start"):
        return {"when": "scene_starts", "line": lineno}
    if body_head[0] == "scene" and len(body_head) > 1 and body_head[1] in ("ends", "end"):
        return {"when": "scene_ends", "line": lineno}
    if body_head[0] == "update":
        return {"when": "update", "line": lineno}
    if body_head[0] == "key":
        key = body_head[1] if len(body_head) > 1 else "Space"
        st = "pressed"
        if len(body_head) > 2 and body_head[2] in ("pressed", "held", "released"):
            st = body_head[2]
        return {"when": "key", "key": key, "key_state": st, "line": lineno}
    if "collides" in body_head:
        k = body_head.index("collides")
        return {"when": "collide", "a": body_head[k-1] if k else "player",
                "b": body_head[k+1] if k+1 < len(body_head) else "crate", "line": lineno}
    if body_head[0] == "every":
        sec = float(body_head[1]) if len(body_head) > 1 and _is_num(body_head[1]) else 1.0
        return {"when": "every", "seconds": sec, "line": lineno}
    if body_head[0] == "clicked":
        return {"when": "clicked", "target": body_head[1] if len(body_head) > 1 else "play", "line": lineno}
    if body_head[0] == "api":
        return {"when": "api", "api": body_head[1] if len(body_head) > 1 else "api", "line": lineno}
    if body_head[0] == "peer":
        return {"when": "peer", "line": lineno}
    if body_head[0] == "message":
        return {"when": "message", "msg": body_head[1] if len(body_head) > 1 else "", "line": lineno}
    for k, op in enumerate(body_head):
        if op in ("<=", ">=", "==", "!=", "<", ">", "is"):
            return {"when": "compare", "left": body_head[k-1], "cmp": "==" if op == "is" else op,
                    "right": body_head[k+1] if k+1 < len(body_head) else "0", "line": lineno}
    raise WindscriptError(lineno, "unknown when '" + " ".join(tokens) + "'")


def _parse_stmt(tokens, lineno):
    if not tokens:
        return None
    op = tokens[0]
    s = {"op": op, "line": lineno}

    def after(word):
        if word in tokens:
            k = tokens.index(word)
            return tokens[k+1] if k+1 < len(tokens) else None
        return None

    if op == "spawn":
        s["name"] = tokens[1] if len(tokens) > 1 else "obj"
        s["as"] = _unq(after("as") or "")
        if "at" in tokens:
            s["at"], _ = _vec(tokens, tokens.index("at") + 1)
        else:
            s["at"] = [0, 1, 0]
        if "size" in tokens:
            s["size"], _ = _vec(tokens, tokens.index("size") + 1)
        s["mesh"] = after("mesh") or "box"
        if "mass" in tokens:
            s["mass"] = float(after("mass") or 0)
        s["collider"] = after("collider") or ("box" if s.get("mass") else "off")
        s["color"] = after("color")
        if s["as"] == "Hero" or s["name"] == "player":
            s["player"] = True
        return s
    if op == "destroy":
        s["name"] = tokens[1]; return s
    if op == "go":
        name = tokens[-1]
        if "scene" in tokens:
            name = tokens[tokens.index("scene") + 1]
        s["op"] = "go"; s["scene"] = name
        return s
    if op == "play":
        if "proc" in tokens:
            s["proc"] = after("proc")
            s["sound"] = s["proc"]
        else:
            s["sound"] = _unq(tokens[1] if len(tokens) > 1 else "tone")
        s["loop"] = "loop" in tokens
        if "volume" in tokens:
            s["volume"] = float(after("volume") or 0.5)
        if "spatial" in tokens:
            s["spatial"] = float(after("spatial") or 12)
        if "at" in tokens:
            s["at"], _ = _vec(tokens, tokens.index("at") + 1)
        return s
    if op == "stop":
        s["sound"] = tokens[1] if len(tokens) > 1 else ""
        return s
    if op == "connect":
        if len(tokens) > 1 and tokens[1] == "peer":
            s["kind"] = "peer"
            s["room"] = _unq(after("room") or "wind")
            return s
        if len(tokens) > 1 and tokens[1] == "supabase":
            s["kind"] = "supabase"
            s["url"] = _unq(tokens[2] if len(tokens) > 2 else "")
            s["key"] = _unq(after("key") or "")
            s["as"] = after("as") or "db"
            return s
        if len(tokens) > 1 and tokens[1] == "api":
            s["kind"] = "api"
            s["url"] = _unq(tokens[2] if len(tokens) > 2 else "")
            s["as"] = after("as") or "api"
            if "every" in tokens:
                s["every"] = float(after("every") or 10)
            s["method"] = after("method") or "GET"
            return s
        if len(tokens) > 1 and tokens[1] == "database":
            s["kind"] = "database"
            s["as"] = tokens[2] if len(tokens) > 2 else "save"
            return s
        s["kind"] = "bind"
        s["src"] = tokens[1] if len(tokens) > 1 else ""
        s["dst"] = after("to") or ""
        return s
    if op == "import":
        s["type"] = tokens[1] if len(tokens) > 1 else "model"
        path = None
        for t in tokens[2:]:
            if t not in ("as",) and not path:
                path = _unq(t)
                break
        s["path"] = path or ""
        s["as"] = after("as") or Path(s["path"]).stem
        return s
    if op == "set":
        s["path"] = tokens[1] if len(tokens) > 1 else "x"
        rest = tokens[2:]
        if rest and rest[0] in ("=", "to"):
            rest = rest[1:]
        s["expr"] = rest
        s["value"] = _unq(rest[0]) if rest else 0
        if rest and _is_num(str(s["value"])) and len(rest) == 1:
            s["value"] = float(s["value"])
        return s
    if op == "add":
        s["path"] = tokens[1] if len(tokens) > 1 else "score"
        s["value"] = float(tokens[2]) if len(tokens) > 2 and _is_num(tokens[2]) else 1
        return s
    if op == "jump":
        s["name"] = tokens[1] if len(tokens) > 1 else "player"
        s["force"] = float(tokens[2]) if len(tokens) > 2 and _is_num(tokens[2]) else 8
        return s
    if op == "move":
        s["name"] = tokens[1] if len(tokens) > 1 else "player"
        s["dir"] = tokens[2] if len(tokens) > 2 else "forward"
        s["speed"] = float(tokens[3]) if len(tokens) > 3 and _is_num(tokens[3]) else 6
        return s
    if op in ("show", "hide"):
        s["name"] = tokens[1] if len(tokens) > 1 else ""
        return s
    if op == "emit":
        s["type"] = tokens[1] if len(tokens) > 1 else "fire"
        if "at" in tokens:
            s["at"], _ = _vec(tokens, tokens.index("at") + 1)
        if "rate" in tokens:
            s["rate"] = float(after("rate") or 40)
        return s
    if op in ("attach", "anchor"):
        s["op"] = "attach"
        s["child"] = tokens[1] if len(tokens) > 1 else ""
        s["parent"] = after("to") or after("parent") or (tokens[2] if len(tokens) > 2 else "")
        if "offset" in tokens:
            s["offset"], _ = _vec(tokens, tokens.index("offset") + 1)
        return s
    if op == "camera":
        if "follow" in tokens:
            s["follow"] = after("follow")
        if "dist" in tokens:
            s["dist"] = float(after("dist") or 8)
        if "height" in tokens:
            s["height"] = float(after("height") or 2.5)
        if "pos" in tokens:
            s["pos"], _ = _vec(tokens, tokens.index("pos") + 1)
        if "look" in tokens:
            s["look"], _ = _vec(tokens, tokens.index("look") + 1)
        return s
    if op == "ui":
        s["kind"] = tokens[1] if len(tokens) > 1 else "text"
        s["id"] = tokens[2] if len(tokens) > 2 else "ui"
        if "at" in tokens:
            xy, _ = _vec(tokens, tokens.index("at") + 1)
            if xy:
                s["x"] = xy[0]
                s["y"] = xy[1] if len(xy) > 1 else 16
        if "width" in tokens:
            s["w"] = float(after("width") or 160)
        for t in reversed(tokens):
            if t.startswith('"'):
                s["text"] = _unq(t)
                break
        return s
    if op == "sky":
        s["top"] = after("top")
        s["horizon"] = after("horizon")
        s["bottom"] = after("bottom")
        return s
    if op == "sun":
        nums, _ = _vec(tokens, 1)
        s["dir"] = nums or [-0.4, -1, -0.3]
        if "color" in tokens:
            s["color"] = after("color")
        return s
    if op == "fog":
        s["color"] = tokens[1] if len(tokens) > 1 else "#9bb8d4"
        if len(tokens) > 2 and _is_num(tokens[2]):
            s["density"] = float(tokens[2])
        return s
    if op == "ambient":
        s["color"] = tokens[1] if len(tokens) > 1 else "#223"
        return s
    if op == "terrain":
        if "size" in tokens:
            s["size"] = float(after("size") or 80)
        if "height" in tokens:
            s["height"] = float(after("height") or 5)
        if "seed" in tokens:
            s["seed"] = float(after("seed") or 1)
        return s
    if op == "grass":
        if "count" in tokens:
            s["count"] = int(float(after("count") or 120))
        if "wind" in tokens:
            s["wind"] = float(after("wind") or 1)
        return s
    if op == "water":
        if "at" in tokens:
            s["at"], _ = _vec(tokens, tokens.index("at") + 1)
        if "size" in tokens:
            s["size"], _ = _vec(tokens, tokens.index("size") + 1)
        return s
    if op == "light":
        if "at" in tokens:
            s["at"], _ = _vec(tokens, tokens.index("at") + 1)
        s["color"] = after("color")
        if "range" in tokens:
            s["range"] = float(after("range") or 10)
        return s
    if op == "log":
        s["msg"] = _unq(" ".join(tokens[1:]))
        return s
    if op == "export":
        return s
    if op == "rename":
        s["from"] = tokens[1] if len(tokens) > 1 else ""
        s["to"] = after("to") or (tokens[2] if len(tokens) > 2 else "")
        return s
    if op == "color":
        s["name"] = tokens[1] if len(tokens) > 1 else ""
        if "gradient" in tokens:
            k = tokens.index("gradient")
            s["gradient"] = [_unq(tokens[k+1]) if k+1 < len(tokens) else "#fff", _unq(tokens[k+2]) if k+2 < len(tokens) else "#000"]
        else:
            s["color"] = tokens[2] if len(tokens) > 2 else tokens[1] if len(tokens) > 1 else "#fff"
        return s
    if op == "animate":
        s["id"] = tokens[1].split(".")[-1] if len(tokens) > 1 else "ui"
        s["mode"] = "frames" if "frames" in tokens else "linear"
        s["dur"] = float(after("linear") or after("frames") or 0.4) if False else 0.4
        for t in tokens:
            if _is_num(t):
                s["dur"] = float(t)
        s["keyframes"] = [{"t": 0, "opacity": 0}, {"t": 1, "opacity": 1}]
        return s
    if op == "graphics":
        s["level"] = tokens[1] if len(tokens) > 1 else "high"
        return s
    if op == "collision":
        s["name"] = tokens[1] if len(tokens) > 1 else ""
        s["on"] = "off" not in tokens and "false" not in tokens
        return s
    if op == "gravity":
        s["y"] = float(tokens[1]) if len(tokens) > 1 and _is_num(tokens[1]) else 0.0
        return s
    if op == "if":
        s["cond"] = _parse_cond(tokens[1:])
        s["then"] = []
        s["else"] = []
        return s
    if op == "else":
        return s
    if op == "let":
        s["name"] = tokens[1] if len(tokens) > 1 else "x"
        rest = tokens[2:]
        if rest and rest[0] in ("=", "is"):
            rest = rest[1:]
        s["expr"] = rest
        s["value"] = _unq(rest[0]) if rest else 0
        if rest and _is_num(str(s["value"])):
            s["value"] = float(s["value"])
        return s
    if op == "for":
        s["var"] = tokens[1] if len(tokens) > 1 else "i"
        rng = [t for t in tokens[2:] if t != "in"]
        text = "".join(rng)
        if ".." in text:
            a, b = text.split("..", 1)
            s["from"] = float(a) if _is_num(a) else 0
            s["to"] = float(b) if _is_num(b) else 0
        elif len(rng) >= 2:
            s["from"] = float(rng[0]) if _is_num(rng[0]) else 0
            s["to"] = float(rng[-1]) if _is_num(rng[-1]) else 0
        else:
            s["from"], s["to"] = 0, 0
        s["body"] = []
        return s
    if op == "repeat":
        s["n"] = float(tokens[1]) if len(tokens) > 1 and _is_num(tokens[1]) else 1
        s["body"] = []
        return s
    if op == "fn":
        s["name"] = tokens[1] if len(tokens) > 1 else "fn"
        s["body"] = []
        return s
    if op == "call":
        s["name"] = tokens[1] if len(tokens) > 1 else ""
        return s
    if op == "send":
        s["msg"] = tokens[1] if len(tokens) > 1 else ""
        return s
    raise WindscriptError(lineno, "unknown statement '" + op + "'")


def parse_windscript(src: str, filename: str = "<wind>") -> dict:
    raw = src.replace("\t", "  ").splitlines()
    rows = []
    for n, line in enumerate(raw, 1):
        cut = line.split("#", 1)[0].rstrip()
        if not cut.strip():
            continue
        indent = len(cut) - len(cut.lstrip(" "))
        rows.append((n, indent, cut.strip()))
    if not rows:
        raise WindscriptError(1, "empty script")

    ast = {
        "title": "Wind Game",
        "mode": "3d",
        "start": None,
        "scenes": [],
        "assets": {"models": {}, "music": {}},
        "file": filename,
    }
    i = 0
    while i < len(rows) and rows[i][1] == 0 and rows[i][2].split()[0] != "scene":
        n, _, text = rows[i]
        tok = _tokenize(text)
        if tok[0] == "game":
            ast["title"] = _unq(tok[1] if len(tok) > 1 else "Wind")
        elif tok[0] == "mode":
            m = (tok[1] if len(tok) > 1 else "3d").lower()
            if m not in ("2d", "3d"):
                raise WindscriptError(n, "mode must be 2d or 3d — no other types")
            ast["mode"] = m
        elif tok[0] == "start":
            ast["start"] = tok[-1]
        elif tok[0] == "title":
            ast["title"] = _unq(tok[1] if len(tok) > 1 else ast["title"])
        else:
            raise WindscriptError(n, "only game/mode/start/title allowed before scenes (found '" + tok[0] + "')")
        i += 1

    def consume_block(start_indent, start_i):
        j = start_i
        kids = []
        while j < len(rows) and rows[j][1] > start_indent:
            kids.append(rows[j])
            j += 1
        return kids, j

    def parse_body(block_rows, parent_indent, lineno_hint):
        body = []
        k = 0
        while k < len(block_rows):
            n, ind, text = block_rows[k]
            tok = _tokenize(text)
            if not tok:
                k += 1
                continue
            if tok[0] == "when":
                raise WindscriptError(n, "events must be at the top of the scene — nest actions under a when, not another when here")
            stmt = _parse_stmt(tok, n)
            if tok[0] in ("if", "for", "fn", "repeat"):
                sub = []
                k += 1
                while k < len(block_rows) and block_rows[k][1] > ind:
                    sub.append(block_rows[k])
                    k += 1
                if tok[0] == "if":
                    stmt["then"] = parse_body(sub, ind, n) if sub else []
                    if k < len(block_rows) and _tokenize(block_rows[k][2])[0] == "else":
                        eind = block_rows[k][1]
                        k += 1
                        esub = []
                        while k < len(block_rows) and block_rows[k][1] > eind:
                            esub.append(block_rows[k])
                            k += 1
                        stmt["else"] = parse_body(esub, eind, n) if esub else []
                else:
                    stmt["body"] = parse_body(sub, ind, n) if sub else []
                body.append(stmt)
                continue
            if tok[0] == "else":
                k += 1
                continue
            body.append(stmt)
            k += 1
        return body

    while i < len(rows):
        n, ind, text = rows[i]
        tok = _tokenize(text)
        if tok[0] != "scene":
            raise WindscriptError(n, "expected 'scene NAME'")
        if len(tok) < 2:
            raise WindscriptError(n, "scene needs a name")
        scene = {"name": tok[1], "events": []}
        kids, nxt = consume_block(ind, i + 1)
        if not kids:
            raise WindscriptError(n, "scene '" + tok[1] + "' is empty — add 'when scene starts'")
        child_indent = kids[0][1]
        p = 0
        saw_stmt = False
        while p < len(kids):
            ln, idn, tx = kids[p]
            if idn != child_indent:
                p += 1
                continue
            t0 = _tokenize(tx)
            if t0[0] != "when":
                raise WindscriptError(
                    ln,
                    "events must be at the top of every block sequence. "
                    "Start with 'when scene starts' / 'when update' / 'when key …' — found '" + t0[0] + "'"
                )
            ev = _parse_when(t0[1:], ln)
            p += 1
            sub = []
            while p < len(kids) and kids[p][1] > child_indent:
                sub.append(kids[p])
                p += 1
            ev["body"] = parse_body(sub, child_indent, ln)
            scene["events"].append(ev)
            saw_stmt = True
        if not scene["events"]:
            raise WindscriptError(n, "scene has no when-events")
        ast["scenes"].append(scene)
        i = nxt

    if not ast["scenes"]:
        raise WindscriptError(1, "no scenes")
    if not ast["start"]:
        ast["start"] = ast["scenes"][0]["name"]
    return ast


def load_wind(path: Path) -> dict:
    ast = parse_windscript(path.read_text(encoding="utf-8"), str(path))
    for sc in ast["scenes"]:
        for ev in sc["events"]:
            for st in ev.get("body") or []:
                if st.get("op") == "import" and st.get("path"):
                    p = Path(st["path"])
                    if not p.is_file():
                        p = path.parent / st["path"]
                    if p.is_file():
                        if st.get("type") == "music":
                            data = base64.b64encode(p.read_bytes()).decode("ascii")
                            mime = "audio/mpeg"
                            if p.suffix.lower() == ".wav":
                                mime = "audio/wav"
                            elif p.suffix.lower() == ".ogg":
                                mime = "audio/ogg"
                            ast["assets"]["music"][st.get("as") or p.stem] = "data:" + mime + ";base64," + data
                            st["data"] = ast["assets"]["music"][st.get("as") or p.stem]
                            st["as"] = st.get("as") or p.stem
                        else:
                            text = p.read_text(encoding="utf-8", errors="ignore")
                            ast["assets"]["models"][st.get("as") or p.stem] = text
                            st["data"] = text
                            st["as"] = st.get("as") or p.stem
    return ast

