def kit_models() -> dict:
    out = {}
    for name, raw in MODELS_B64.items():
        out[name] = base64.b64decode(raw).decode("utf-8", errors="ignore")
    return out


def kit_mtl() -> dict:
    out = {}
    for name, raw in MTL_B64.items():
        out[name] = base64.b64decode(raw).decode("utf-8", errors="ignore")
    return out


def kit_textures() -> dict:
    out = {}
    for name, raw in TEXTURES_B64.items():
        out[name] = "data:image/png;base64," + "".join(raw.split())
    return out


def wasm_b64() -> str:
    return WASM_B64_EMBED or ""


def runtime_js() -> str:
    if not RUNTIME_B64:
        raise SystemExit("runtime missing")
    return base64.b64decode(RUNTIME_B64).decode("utf-8")


def try_wasm():
    b64 = wasm_b64()
    if not b64:
        return None, "no wasm bytes"
    try:
        from wasmtime import Store, Module, Instance, Engine
        raw = base64.b64decode(b64)
        eng = Engine()
        store = Store(eng)
        inst = Instance(store, Module(eng, raw), [])
        ex = inst.exports(store)
        noise2 = lambda x, y: ex["noise2"](store, float(x), float(y))
        return {"store": store, "ex": ex, "noise2": noise2, "version": lambda: ex["version"](store)}, "ok"
    except Exception as e:
        return None, str(e)


def inject_kit(ast: dict) -> dict:
    ast.setdefault("assets", {}).setdefault("models", {})
    ast["assets"].setdefault("music", {})
    ast["assets"].setdefault("mtl", {})
    ast["assets"].setdefault("textures", {})
    kit = kit_models()
    for k, v in kit.items():
        ast["assets"]["models"].setdefault(k, v)
    for k, v in kit_mtl().items():
        ast["assets"]["mtl"].setdefault(k, v)
    for k, v in kit_textures().items():
        ast["assets"]["textures"].setdefault(k, v)
    return ast


def load_wind(path: Path) -> dict:
    ast = parse_windscript(path.read_text(encoding="utf-8"), str(path))
    for sc in ast["scenes"]:
        for ev in sc["events"]:
            for st in ev.get("body") or []:
                if st.get("op") == "import" and st.get("path"):
                    p = Path(st["path"])
                    if not p.is_file():
                        p = path.parent / st["path"]
                    if not p.is_file() and st["path"] in kit_models():
                        st["data"] = kit_models()[st["path"]]
                        st["as"] = st.get("as") or st["path"]
                        ast["assets"]["models"][st["as"]] = st["data"]
                        continue
                    if p.is_file():
                        if st.get("type") == "music":
                            data = base64.b64encode(p.read_bytes()).decode("ascii")
                            mime = "audio/mpeg"
                            if p.suffix.lower() == ".wav":
                                mime = "audio/wav"
                            elif p.suffix.lower() == ".ogg":
                                mime = "audio/ogg"
                            ast["assets"]["music"][st.get("as") or p.stem] = "data:" + mime + ";base64," + data
                            st["data"] = ast["assets"]["music"][st.get("as") or p.stem]
                            st["as"] = st.get("as") or p.stem
                        else:
                            text = p.read_text(encoding="utf-8", errors="ignore")
                            key = st.get("as") or p.stem
                            ast["assets"]["models"][key] = text
                            st["data"] = text
                            st["as"] = key
                            mtlp = p.with_suffix(".mtl")
                            if mtlp.is_file():
                                mt = mtlp.read_text(encoding="utf-8", errors="ignore")
                                ast["assets"].setdefault("mtl", {})[key] = mt
                                st["mtl"] = mt
                            for ext, mime in ((".png", "image/png"), (".jpg", "image/jpeg"), (".jpeg", "image/jpeg"), (".webp", "image/webp")):
                                tp = p.with_suffix(ext)
                                if tp.is_file():
                                    data = "data:" + mime + ";base64," + base64.b64encode(tp.read_bytes()).decode("ascii")
                                    ast["assets"].setdefault("textures", {})[key] = data
                                    st["tex"] = data
                                    break
    return inject_kit(ast)


def headless_see(ast: dict, steps: int = 30) -> str:
    wasm, wmsg = try_wasm()
    sc = ast["start"]
    ents = []
    for scene in ast["scenes"]:
        if scene["name"] != sc:
            continue
        for ev in scene["events"]:
            if ev.get("when") == "scene_starts":
                for st in ev.get("body") or []:
                    if st.get("op") == "spawn":
                        at = st.get("at") or [0, 0, 0]
                        ents.append({"name": st.get("name"), "mesh": st.get("mesh"), "pos": at})
    lines = [
        f"Wind Engine {VERSION}  mode={ast['mode']}  scene={sc}  wasm={wmsg}",
        f"title: {ast['title']}",
        f"scenes: " + ", ".join(s["name"] for s in ast["scenes"]),
        f"kit models: " + ", ".join(sorted(kit_models())),
        f"entities after 'when scene starts': {len(ents)}",
    ]
    for e in ents[:24]:
        lines.append(f"  {e['name']}  mesh={e['mesh']}  pos={e['pos']}")
    if wasm:
        lines.append(f"WASM version {wasm['version']()}  noise2(1.2,3.4)={wasm['noise2'](1.2, 3.4):.6f}")
        if steps:
            ex, store = wasm["ex"], wasm["store"]
            n = min(len(ents), 8) or 1
            ex["integrate"](store, n, 0.016, 0.0, -22.0, 0.0)
            lines.append(f"WASM integrate({n}, dt=0.016) ran")
    return "\n".join(lines)


def html_page(ast: dict) -> str:
    rt = runtime_js()
    b64 = wasm_b64()
    title = ast.get("title") or "Wind"
    payload = json.dumps(ast, ensure_ascii=False)
    wasm_js = json.dumps(b64)
    peer = ""
    if PEERJS_B64:
        peer = "<script>\n" + base64.b64decode(PEERJS_B64).decode("utf-8") + "\n</script>\n"
    return (
        "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n"
        "<meta charset=\"utf-8\"><title>" + title.replace("<", "") + "</title>\n"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,user-scalable=no,viewport-fit=cover\">\n"
        "<meta name=\"mobile-web-app-capable\" content=\"yes\">\n"
        "<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n"
        "<style>\n"
        "html,body{margin:0;height:100%;background:#000;overflow:hidden;font:14px/1.35 ui-sans-serif,system-ui,sans-serif;color:#eef;touch-action:none}\n"
        "#stage{position:fixed;inset:0}\n"
        "#c{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}\n"
        "#hud{position:absolute;inset:0;pointer-events:none}\n"
        "#hud .wbtn{pointer-events:auto}\n"
        ".wui,.wbtn{position:absolute;color:#fff;text-shadow:0 1px 3px #000;font-weight:600}\n"
        ".wbtn{background:#1c2638cc;border:1px solid #e8b86d;border-radius:8px;padding:8px 14px;cursor:pointer;color:#fff}\n"
        ".wbar{position:absolute;height:8px;background:#0008;border:1px solid #fff3;border-radius:4px;overflow:hidden}\n"
        ".wbar i{display:block;height:100%;background:#e35d5d}\n"
        "#fail{display:none;position:fixed;inset:0;align-items:center;justify-content:center;background:#100808ee;color:#f88;padding:24px;z-index:9}\n"
        "</style>\n</head>\n<body>\n"
        "<div id=\"stage\"><canvas id=\"c\"></canvas><div id=\"hud\"></div></div>\n"
        "<div id=\"fail\"></div>\n"
        + peer +
        "<script>\n" + rt + "\n</script>\n<script>\n"
        "const AST = " + payload + ";\n"
        "const WASM_B64 = " + wasm_js + ";\n"
        "const fail = document.getElementById('fail');\n"
        "function boom(e){ fail.style.display='flex'; fail.textContent = String(e && e.stack || e); }\n"
        "Promise.resolve(WindBoot(document.getElementById('c'), document.getElementById('hud'), AST, { wasmB64: WASM_B64, mode: AST.mode }))"
        ".then(function(eng){ window.W = eng; if (eng.bootError && AST.mode === '3d') boom(eng.bootError); })"
        ".catch(boom);\n"
        "</script>\n</body></html>\n"
    )


def make_icon(width: int = 52, height: int = 16) -> str:
    ramp = " .'`^:-=+*#%%@@"
    lines = []
    for j in range(height):
        y = 1.0 - j / max(1, height - 1) * 2.0
        row = []
        for i in range(width):
            x = i / max(1, width - 1) * 2.0 - 1.0
            r = math.hypot(x + 0.15, y)
            vortex = math.atan2(y, x + 0.15)
            swirl = math.sin(vortex * 3.0 + r * 9.0) * math.exp(-r * 1.35)
            streak = math.exp(-((y - 0.12 * math.sin(x * 6.0)) ** 2) * 16.0) * (0.35 + 0.65 * (x + 1) / 2)
            stem = 0.9 if abs(x) < 0.035 and y < 0.25 else 0.0
            v = abs(swirl) * 0.75 + streak * 0.95 + stem
            k = int(max(0, min(len(ramp) - 1, v * (len(ramp) - 1))))
            row.append(ramp[k])
        lines.append("".join(row))
    return "\n" + "\n".join(lines) + "\n"


def banner():
    print(make_icon())
    print(f"Wind Engine {VERSION}  ·  Windscript  ·  Rust WASM  ·  CLI")
    print(COMMANDS)


def list_templates():
    print("templates")
    for k, (desc, src) in TEMPLATES.items():
        mode = "2d" if "\nmode 2d" in src or src.startswith("mode 2d") or "mode 2d\n" in src else "3d"
        print(f"  {k:18}  {mode}  {desc}")


def cmd_new(name: str, out: Path):
    key = name.strip().lower().replace("_", "-")
    aliases = {
        "platformer": "2d-platformer", "valley": "3d-explore", "fps": "3d-fps",
        "multiplayer": "3d-multiplayer", "mp": "3d-multiplayer", "coop": "3d-coop",
        "racing": "3d-racing", "flight": "3d-flight", "survival": "3d-survival",
        "pong": "2d-pong", "breakout": "2d-breakout", "topdown": "2d-topdown",
        "runner": "2d-runner", "puzzle": "2d-puzzle",
    }
    key = aliases.get(key, key)
    if key not in TEMPLATES:
        print("unknown template:", name)
        list_templates()
        sys.exit(2)
    desc, src = TEMPLATES[key]
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(src, encoding="utf-8")
    print(f"wrote {out}  ({key} · {desc})")


def write_stock_games():
    GAMES.mkdir(parents=True, exist_ok=True)
    for key, (_d, src) in TEMPLATES.items():
        (GAMES / (key + ".wind")).write_text(src, encoding="utf-8")
    (GAMES / "platformer.wind").write_text(TEMPLATES["2d-platformer"][1], encoding="utf-8")
    (GAMES / "valley.wind").write_text(TEMPLATES["3d-explore"][1], encoding="utf-8")


def cmd_export(wind_path: Path, out: Path):
    ast = load_wind(wind_path)
    out.write_text(html_page(ast), encoding="utf-8")
    print("exported", out)
    print("  game", ast["title"], "mode", ast["mode"])
    print("  html is the game only")


def cmd_serve(wind_path: Path, port: int, host: str):
    ast = load_wind(wind_path)
    html = html_page(ast)
    blob = html.encode("utf-8")

    class H(BaseHTTPRequestHandler):
        def do_GET(self):
            path = self.path.split("?", 1)[0]
            if path in ("/", "/index.html", "/game.html"):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(blob)))
                self.end_headers()
                self.wfile.write(blob)
                return
            self.send_error(404)

        def log_message(self, fmt, *args):
            sys.stderr.write("[http] " + (fmt % args) + "\n")

    httpd = ThreadingHTTPServer((host, port), H)
    wasm, wmsg = try_wasm()
    banner()
    print(f"  WASM     {wmsg}")
    print(f"  game     {ast['title']}  mode={ast['mode']}  file={wind_path}")
    print(f"  url      http://{host}:{port}/")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nstop")


