def cmd_models(q: str | None):
    print("bundled CC0 models (Kenney / KayKit — public domain)")
    for k in sorted(MODELS_B64):
        raw = base64.b64decode(MODELS_B64[k])
        if q and q.lower() not in k.lower():
            continue
        print(f"  {k:12}  {len(raw):6} bytes   spawn … mesh {k}")
    print("fetch more:  python wind.py fetch kenney/nature-kit/tree_palm")
    print("catalog:     https://github.com/Mcamento8/omnimod-3d-library")


def cmd_fetch(ident: str):
    ident = ident.strip().lstrip("/")
    if ".." in ident or ident.startswith("http"):
        print("use an OmniMod id like kenney/mini-characters/character-male-b")
        sys.exit(2)
    url = "https://raw.githubusercontent.com/Mcamento8/omnimod-3d-library/main/models/" + ident + ".obj"
    dest_dir = HERE / "assets" / "models"
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / (ident.replace("/", "_") + ".obj")
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "wind-engine"})
        with urllib.request.urlopen(req, timeout=30) as r:
            data = r.read()
        if data.startswith(b"404") or len(data) < 40:
            raise RuntimeError("not found")
        dest.write_bytes(data)
        print("wrote", dest, len(data), "bytes")
        print(f'  import model "{dest}" as {Path(ident).name.replace("-", "_")}')
    except Exception as e:
        print("fetch failed:", e)
        sys.exit(2)


def cmd_tex(w: int, h: int, out: Path, kind: str):
    w = max(1, min(2048, w))
    h = max(1, min(2048, h))
    pix = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            n = math.sin(x * 0.11 + y * 0.07) * 0.5 + math.sin(x * 0.03 - y * 0.09) * 0.5
            n = (n + 1) * 0.5
            if kind == "noise":
                n = (math.sin(x * 12.9898 + y * 78.233) * 43758.5453) % 1.0
            v = int(max(0, min(255, n * 255)))
            i = (y * w + x) * 3
            if kind == "fill":
                pix[i] = 40; pix[i+1] = 90; pix[i+2] = 180
            else:
                pix[i] = v
                pix[i+1] = (v * 3) // 4
                pix[i+2] = 40 + v // 3
    out.write_bytes(b"P6\n%d %d\n255\n" % (w, h) + bytes(pix))
    print("wrote", out, w, "x", h, kind)


