def cmd_bench():
    wasm, wmsg = try_wasm()
    print("wasm", wmsg)
    if not wasm:
        sys.exit(1)
    t0 = time.perf_counter()
    s = 0.0
    for i in range(20000):
        s += wasm["noise2"](i * 0.017, i * 0.013)
    t1 = time.perf_counter()
    print(f"noise2 x20000  {t1-t0:.4f}s  acc={s:.4f}")
    ex, store = wasm["ex"], wasm["store"]
    t0 = time.perf_counter()
    for _ in range(5000):
        ex["integrate"](store, 64, 0.016, 0.0, -22.0, 0.0)
    t1 = time.perf_counter()
    print(f"integrate(64) x5000  {t1-t0:.4f}s  version={wasm['version']()}")


def cmd_inspect(path: Path):
    ast = load_wind(path)
    slim = json.loads(json.dumps(ast))
    slim.get("assets", {}).pop("models", None)
    print(json.dumps(slim, indent=2)[:8000])


def cmd_test() -> int:
    fails = []
    def ok(name, cond, detail=""):
        if cond:
            print("  PASS", name)
        else:
            print("  FAIL", name, detail)
            fails.append(name)

    print("Wind Engine self-test")
    wasm, wmsg = try_wasm()
    ok("wasm-load", wasm is not None, wmsg)
    if wasm:
        ok("wasm-version", wasm["version"]() == 300, str(wasm["version"]()))
        n = wasm["noise2"](1.2, 3.4)
        ok("wasm-noise-finite", math.isfinite(n), str(n))
        ok("wasm-noise-stable", wasm["noise2"](1.2, 3.4) == n)
        ex, store = wasm["ex"], wasm["store"]
        ptr = ex["bodies_ptr"](store)
        stride = ex["bodies_stride"](store)
        ok("wasm-layout", stride == 16 and ptr >= 0, f"ptr={ptr} stride={stride}")
        mem = ex["memory"]
        # static body must not fall: inv=0, y=10
        buf = mem.read(store, 0, mem.data_len(store)) if hasattr(mem, "read") else None
        try:
            mv = memoryview(mem)
        except Exception:
            mv = None
        if hasattr(ex["integrate"], "__call__"):
            ex["integrate"](store, 1, 0.016, 0.0, -22.0, 0.0)
            ok("wasm-integrate-call", True)

    write_stock_games()
    for p in sorted(GAMES.glob("*.wind")):
        try:
            ast = load_wind(p)
            ok("parse-" + p.name, ast["mode"] in ("2d", "3d") and ast["scenes"])
        except Exception as e:
            ok("parse-" + p.name, False, str(e))

    try:
        parse_windscript("game X\nmode 3d\nscene a\n  spawn z at 0,0,0\n", "t")
        ok("events-first", False, "should reject spawn before when")
    except WindscriptError:
        ok("events-first", True)

    try:
        parse_windscript("game X\nmode 4d\nscene a\n  when scene starts\n    log hi\n", "t")
        ok("mode-guard", False)
    except WindscriptError:
        ok("mode-guard", True)

    ast = parse_windscript(TEMPLATES["3d-explore"][1], "valley")
    html = html_page(inject_kit(ast))
    ok("html-game-only", 'id="pick"' not in html and "<canvas id=\"c\">" in html)
    ok("html-no-editor", 'id="ed"' not in html)
    ok("html-wasm", "WASM_B64" in html and len(b64 := __import__("re").search(r'const WASM_B64 = "([^"]*)"', html).group(1)) > 100)
    ok("html-boot", "WindBoot" in html)
    ok("html-no-cdn", "unpkg.com" not in html and "<script src=\"http" not in html)
    ok("html-peer-inlined", "RTCPeerConnection" in html)
    ok("html-kit-inlined", "mtllib" in html and "humanoid" in html)
    ok("kit-humanoid", "humanoid" in kit_models())
    ok("runtime-grass", "geoGrass" in runtime_js() and "uGrass" in runtime_js())
    ok("runtime-mtl", "parseMTL" in runtime_js())
    ok("kit-tex", "humanoid" in kit_textures() and kit_textures()["humanoid"].startswith("data:image/png"))
    ok("kit-mtl-tree", "Kd" in kit_mtl().get("tree", ""))
    complex = """game X
mode 3d
start scene a
scene a
  when scene starts
    let n = 3
    for i in 1..3
      spawn crate at 0, 1, 0 mesh box
    fn burst
      emit fire at 0, 1, 0
    call burst
  when message ping
    log pong
  when update
    if key W held and player.y > -50
      move player forward 6
    else
      log idle
"""
    try:
        astc = parse_windscript(complex, "c")
        ops = [st.get("op") for st in astc["scenes"][0]["events"][0]["body"]]
        ok("windscript-complex", "let" in ops and "for" in ops and "fn" in ops)
        ok("windscript-else", any(ev.get("when")=="update" and any(x.get("else") is not None for x in ev.get("body") or []) for ev in astc["scenes"][0]["events"]))
    except Exception as e:
        ok("windscript-complex", False, str(e))

    ok("icon", "@" in make_icon() or "#" in make_icon())

    print(f"{len(fails)} failed, {0 if fails else 'all'} ok")
    return 1 if fails else 0


def cmd_repl(path: Path | None):
    ast = load_wind(path) if path else {
        "title": "scratch", "mode": "3d", "start": "main",
        "scenes": [{"name": "main", "events": [{"when": "scene_starts", "body": [], "line": 1}]}],
        "assets": {"models": {}, "music": {}},
    }
    print("Wind REPL. see  mode 2d|3d  quit")
    while True:
        try:
            line = input("wind> ")
        except EOFError:
            break
        s = line.strip()
        if s in ("quit", "exit"):
            break
        if s == "see":
            print(headless_see(ast))
            continue
        if s.startswith("mode "):
            m = s.split()[1].lower()
            if m not in ("2d", "3d"):
                print("mode must be 2d or 3d")
                continue
            ast["mode"] = m
            print("mode", m)
            continue
        print("ok")


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    p = argparse.ArgumentParser(prog="wind.py", add_help=True)
    sub = p.add_subparsers(dest="cmd")
    n = sub.add_parser("new")
    n.add_argument("template")
    n.add_argument("out", nargs="?")
    sub.add_parser("templates")
    sub.add_parser("tools")
    s = sub.add_parser("serve")
    s.add_argument("file")
    s.add_argument("--port", type=int, default=8080)
    s.add_argument("--host", default="0.0.0.0")
    r = sub.add_parser("run")
    r.add_argument("file")
    e = sub.add_parser("export")
    e.add_argument("file")
    e.add_argument("out", nargs="?", default="game.html")
    se = sub.add_parser("see")
    se.add_argument("file")
    rp = sub.add_parser("repl")
    rp.add_argument("file", nargs="?")
    sub.add_parser("test")
    sub.add_parser("lang")
    sub.add_parser("bench")
    md = sub.add_parser("models")
    md.add_argument("query", nargs="?")
    ft = sub.add_parser("fetch")
    ft.add_argument("id")
    tx = sub.add_parser("tex")
    tx.add_argument("w", type=int)
    tx.add_argument("h", type=int)
    tx.add_argument("out", nargs="?", default="tex.ppm")
    tx.add_argument("--kind", default="noise")
    ch = sub.add_parser("check")
    ch.add_argument("file")
    ins = sub.add_parser("inspect")
    ins.add_argument("file")
    if not argv:
        banner()
        return
    args = p.parse_args(argv)
    cmd = args.cmd
    try:
        if cmd == "templates":
            write_stock_games()
            banner()
            list_templates()
        elif cmd == "tools":
            cmd_tools()
        elif cmd == "new":
            out = Path(args.out) if args.out else GAMES / (args.template + ".wind")
            cmd_new(args.template, out)
        elif cmd == "serve":
            cmd_serve(Path(args.file), args.port, args.host)
        elif cmd == "run":
            print(headless_see(load_wind(Path(args.file))))
        elif cmd == "see":
            print(headless_see(load_wind(Path(args.file))))
        elif cmd == "export":
            cmd_export(Path(args.file), Path(args.out))
        elif cmd == "repl":
            cmd_repl(Path(args.file) if args.file else None)
        elif cmd == "test":
            sys.exit(cmd_test())
        elif cmd == "lang":
            cmd_lang()
        elif cmd == "bench":
            cmd_bench()
        elif cmd == "models":
            cmd_models(args.query)
        elif cmd == "fetch":
            cmd_fetch(args.id)
        elif cmd == "tex":
            cmd_tex(args.w, args.h, Path(args.out), args.kind)
        elif cmd == "check":
            ast = load_wind(Path(args.file))
            print("ok", ast["title"], ast["mode"], len(ast["scenes"]), "scenes")
        elif cmd == "inspect":
            cmd_inspect(Path(args.file))
        else:
            banner()
    except WindscriptError as e:
        print(e, file=sys.stderr)
        sys.exit(2)


if __name__ == "__main__":
    main()
